 import { supabase } from '../lib/supabase';

const YOCO_PUBLIC_KEY = process.env.REACT_APP_YOCO_PUBLIC_KEY;

export async function initiatePayment({
  amount,
  currency = 'ZAR',
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community',
}) {
  try {
    // 1. Calculate fees (30% platform, 70% creator)
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. Construct the Yoco Checkout URL dynamically
    // This uses Yoco's public "Checkout" endpoint which accepts the amount and currency
    const checkoutUrl = `https://pay.yoco.com/api/checkout?key=${YOCO_PUBLIC_KEY}&amount=${Math.round(amount * 100)}&currency=${currency}`;

    // 4. Redirect the user to the dynamically generated checkout page
    window.location.href = checkoutUrl;

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Yoco payment error:', error);
    return { success: false, error: error.message };
  }
}
